-- ==============================================================================
-- RitmoFlow (Salsa Explosion UK) - Database Security Migration
-- Enable Row Level Security (RLS) on all 19 Public Tables
-- 
-- STATUS: PROPOSED / READY FOR REVIEW (DO NOT EXECUTE AUTOMATICALLY)
-- Target Database: Supabase PostgreSQL (Production / Staging)
-- Description:
--   Enables Row Level Security on all 19 public tables generated by Prisma.
--   Because the application communicates exclusively via Prisma using the
--   privileged 'postgres' database role (which owns the tables and holds
--   the BYPASSRLS attribute), enabling RLS without anon policies enforces
--   a strict DEFAULT DENY for PostgREST / anon API keys without affecting
--   application queries, server actions, or Next.js server components.
-- ==============================================================================

BEGIN;

-- 1. Core User & Identity
ALTER TABLE public."User" ENABLE ROW LEVEL SECURITY;

-- 2. Class Scheduling, Bookings & Attendance
ALTER TABLE public."ClassSession" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Booking" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."PartnerWaitlistEntry" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."PrivateLessonBooking" ENABLE ROW LEVEL SECURITY;

-- 3. Student Submissions & Multimodal Coaching
ALTER TABLE public."VideoSubmission" ENABLE ROW LEVEL SECURITY;

-- 4. Billing, Subscriptions & Credit Ledger
ALTER TABLE public."Subscription" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."CreditLedger" ENABLE ROW LEVEL SECURITY;

-- 5. Events, Festivals & Ticketing
ALTER TABLE public."Event" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."EventTicketTier" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."EventRegistration" ENABLE ROW LEVEL SECURITY;

-- 6. Webhooks & Idempotency
ALTER TABLE public."ProcessedWebhookEvent" ENABLE ROW LEVEL SECURITY;

-- 7. Community, Merchandise & Student Engagement
ALTER TABLE public."MerchReservation" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."AnonymousQuestion" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."PostClassFeedback" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."PublishedAnnouncement" ENABLE ROW LEVEL SECURITY;

-- 8. Forensic Audit & Compliance
ALTER TABLE public."AuditLog" ENABLE ROW LEVEL SECURITY;

-- 9. Cuban Music Practice & Player Analytics
ALTER TABLE public."SongSectionProgress" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."PracticeSectionStat" ENABLE ROW LEVEL SECURITY;

COMMIT;

-- ==============================================================================
-- VERIFICATION QUERY
-- Run this query after applying to confirm all 19 public tables have RLS enabled:
-- ==============================================================================
/*
SELECT 
    schemaname,
    tablename,
    rowsecurity
FROM pg_tables 
WHERE schemaname = 'public' 
  AND tablename IN (
    'User', 'ClassSession', 'Booking', 'VideoSubmission',
    'Subscription', 'CreditLedger', 'Event', 'EventTicketTier',
    'EventRegistration', 'ProcessedWebhookEvent', 'PartnerWaitlistEntry',
    'PrivateLessonBooking', 'MerchReservation', 'AnonymousQuestion',
    'PostClassFeedback', 'AuditLog', 'PublishedAnnouncement',
    'SongSectionProgress', 'PracticeSectionStat'
  )
ORDER BY tablename;
-- Expected Result: 19 rows with rowsecurity = true
*/

